WHERE a.deleted_at IS NULL
AND a.category_cd = #{categoryCd}
AND a.status_cd = #{statusCd}
AND a.assigned_user_id = #{assignedUserId}

   AND (LOWER(a.asset_no) LIKE LOWER('%' || #{keyword} || '%')
        OR LOWER(a.asset_nm) LIKE LOWER('%' || #{keyword} || '%')
        OR LOWER(COALESCE(a.serial_no,'')) LIKE LOWER('%' || #{keyword} || '%')
        OR LOWER(COALESCE(u.name,'')) LIKE LOWER('%' || #{keyword} || '%'))
